                req.age_key_file.clone(),
                Some(req.profile.clone()),
                req.if_missing.clone(),
                req.no_defaults,
                req.non_interactive,
            );
            let config = Config::load_smart(&req.config)?;
            let Some(secret_config) = config.get_secret(&req.profile, &req.key).cloned() else {
                return Ok(Response::Resolved {
                    values: [(req.key, None)].into_iter().collect(),
                });
            };
            let batch_req = ResolveBatchRequest {
                cwd: req.cwd,
                config: req.config,
                profile: req.profile,
                age_key_file: req.age_key_file,
                if_missing: req.if_missing,
                no_defaults: req.no_defaults,
                non_interactive: req.non_interactive,
                purpose: req.purpose,
                keys: vec![req.key.clone()],
                include_env_false: true,
                env: req.env,
            };
            let values = resolve_with_cache(
                &config,
                &batch_req.profile,
                [(req.key, secret_config)].into_iter().collect(),
                &batch_req,
                state,
            )
            .await?;
            Ok(Response::Resolved { values })
        }
    }
}

fn apply_request_settings(
    age_key_file: Option<PathBuf>,
    profile: Option<String>,
    if_missing: Option<String>,
    no_defaults: bool,
    non_interactive: bool,
) {
    crate::settings::Settings::set_cli_snapshot(crate::settings::CliSnapshot {
        age_key_file,
        profile,
        if_missing,
        no_defaults,
    });
    crate::env::set_non_interactive(non_interactive);
}

async fn resolve_with_cache(
    config: &Config,
    profile: &str,
    secrets: IndexMap<String, SecretConfig>,
    req: &ResolveBatchRequest,
    state: std::sync::Arc<Mutex<DaemonState>>,
) -> Result<IndexMap<String, Option<String>>> {
    let fingerprint = config_fingerprint(config, &req.env)?;
    let providers = config.get_providers(profile);
    let mut results = IndexMap::new();
    let mut misses = IndexMap::new();
    let mut miss_keys = HashMap::new();

    {
        let state = state.lock().await;
        for (key, secret) in &secrets {
            let cacheable = req.purpose != Purpose::Check.as_str()
                && secret.daemon_cache.unwrap_or(true)
                && secret
                    .provider()
                    .and_then(|p| providers.get(p))
                    .is_none_or(|p| p.daemon_cache_enabled());
            if cacheable {
                let cache_key = cache_key(&fingerprint, profile, key, secret, req);
                if let Some(value) = state.cache.get(&cache_key) {
                    results.insert(key.clone(), value.clone());
                    continue;
                }
                miss_keys.insert(key.clone(), cache_key);
            }
            misses.insert(key.clone(), secret.clone());
        }
    }

    if !misses.is_empty() {
        let resolved = resolve_secrets_batch(config, profile, &misses).await?;
        let mut state = state.lock().await;
        for (key, value) in resolved {
            if let Some(cache_key) = miss_keys.remove(&key) {
                state.cache.insert(cache_key, value.clone());
            }
            results.insert(key, value);
        }
    }

    let mut ordered = IndexMap::new();
    for key in secrets.keys() {
        if let Some(value) = results.swap_remove(key) {
            ordered.insert(key.clone(), value);
        }
    }
    Ok(ordered)
}

fn cache_key(
    fingerprint: &str,
    profile: &str,
    key: &str,
    secret: &SecretConfig,
    req: &ResolveBatchRequest,
) -> CacheKey {
    let mut hasher = blake3::Hasher::new();
    hasher.update(fingerprint.as_bytes());
    hasher.update(profile.as_bytes());
    hasher.update(req.no_defaults.to_string().as_bytes());
    hasher.update(key.as_bytes());
    hasher.update(req.purpose.as_bytes());
    hasher.update(serde_json::to_string(secret).unwrap_or_default().as_bytes());
    // Split ready keys into provider-backed and no-provider
    let mut by_provider: HashMap<String, Vec<(String, String)>> = HashMap::new();
    let mut level_no_provider = Vec::new();

    for key in ready {
        if let Some((provider_name, provider_value)) = secret_provider.get(key) {
            by_provider
                .entry(provider_name.clone())
                .or_default()
                .push((key.clone(), provider_value.clone()));
        } else if no_provider.contains(key) {
            level_no_provider.push(key.clone());
        }
    }

    let mut temp_results = HashMap::new();

    // Resolve provider-backed secrets in parallel by provider
    let provider_results: Vec<_> = stream::iter(by_provider)
        .map(|(provider_name, provider_secrets)| async move {
            resolve_provider_batch(
                config,
                profile,
                secrets,
                &provider_name,
                provider_secrets,
                resolved_so_far,
            )
            .await
        })
        .buffer_unordered(10)
        .collect()
        .await;

    for provider_result in provider_results {
        temp_results.extend(provider_result?);
    }

    // Resolve no-provider secrets in parallel
    let no_provider_results: Vec<Result<_>> = stream::iter(level_no_provider)
        .map(|key| async move {
            let secret_config = &secrets[&key];
            let value =
                resolve_no_provider_secret(config, profile, &key, secret_config, resolved_so_far)
                    .await?;
            Ok((key, value))
        })
        .buffer_unordered(10)
        .collect()
        .await;

    for result in no_provider_results {
        let (key, value) = result?;
        temp_results.insert(key, value);
    }

    Ok(temp_results)
}

async fn resolve_no_provider_secret(
    config: &Config,
    profile: &str,
    key: &str,
    secret_config: &SecretConfig,
    resolved_so_far: &HashMap<String, Option<String>>,
) -> Result<Option<String>> {
    if let Some(value) = resolve_default_value(key, secret_config, resolved_so_far)? {
        return Ok(Some(value));
    }

    resolve_secret_raw(config, profile, key, secret_config).await
}

/// Resolve all secrets for a single provider using batch operations
async fn resolve_provider_batch(
    config: &Config,
    profile: &str,
    secrets: &IndexMap<String, SecretConfig>,
    provider_name: &str,
    provider_secrets: Vec<(String, String)>,
    resolved_so_far: &HashMap<String, Option<String>>,
) -> Result<HashMap<String, Option<String>>> {
    let mut results = HashMap::new();

    tracing::debug!(
        "Resolving {} secrets from provider '{}' using batch",
        provider_secrets.len(),
        provider_name
    );

    // Get the provider config
    let providers = config.get_providers(profile);
    let provider_config = match providers.get(provider_name) {
        Some(config) => config,
        None => {
            // Find similar provider names for suggestion
            let available_providers: Vec<_> = providers.keys().map(|s| s.as_str()).collect();
            let similar = find_similar(provider_name, available_providers);
            let suggestion = format_suggestions(&similar);

            // Provider not configured, handle errors for all secrets
            let fallback_keys: Vec<String> = provider_secrets
                .iter()
                .map(|(key, _)| key.clone())
                .collect();
            let fallback_resolved =
                resolve_default_fallbacks(&fallback_keys, secrets, resolved_so_far, &mut results)?;
            for (key, _) in &provider_secrets {
                if fallback_resolved.contains(key) {
                    log_provider_default_fallback(
                        key,
                        &FnoxError::ProviderNotConfigured {
                            provider: provider_name.to_string(),
                            profile: profile.to_string(),
                            config_path: None,
                            suggestion: suggestion.clone(),
                        },
                    );
                    continue;
                }

                let secret_config = &secrets[key];
                let if_missing = resolve_if_missing_behavior(secret_config, config);
                let error = FnoxError::ProviderNotConfigured {
                    provider: provider_name.to_string(),
                    profile: profile.to_string(),
                    config_path: config.provider_sources.get(provider_name).cloned(),
                    suggestion: suggestion.clone(),
                };
                if let Some(error) = handle_provider_error(key, error, if_missing, true) {
                    // Fail fast if if_missing is error
                    return Err(error);
                }
                results.insert(key.clone(), None);
            }
            return Ok(results);
        }
    };

    // Skip interactive providers in non-interactive mode (e.g. TUI).
    // Handle per-secret if_missing policy (like ProviderNotConfigured above)
    // so other providers at the same resolution level are not affected.
    if crate::env::is_non_interactive() && provider_config.requires_interactive_auth() {
        let fallback_keys: Vec<String> = provider_secrets
            .iter()
            .map(|(key, _)| key.clone())
            .collect();
        let fallback_resolved =
            resolve_default_fallbacks(&fallback_keys, secrets, resolved_so_far, &mut results)?;
        for (key, _) in &provider_secrets {
            if fallback_resolved.contains(key) {
                log_provider_default_fallback(
                    key,
                    &FnoxError::Provider(format!(
                        "Provider '{}' requires interactive authentication and cannot be used in non-interactive mode. Use 'fnox exec' instead.",
                        provider_name
                    )),
                );
                continue;
            }

            let secret_config = &secrets[key];
            let if_missing = resolve_if_missing_behavior(secret_config, config);
            let error = FnoxError::Provider(format!(
                "Provider '{}' requires interactive authentication and cannot be used in non-interactive mode. Use 'fnox exec' instead.",
                provider_name
            ));
            if let Some(error) = handle_provider_error(key, error, if_missing, true) {
                return Err(error);
            }
            results.insert(key.clone(), None);
        }
        return Ok(results);
    }

    let ctx = ProviderBatchContext {
        config,
        profile,
        secrets,
        provider_name,
        provider_config,
        secret
    }

    fn plain_provider_secret(value: &str) -> SecretConfig {
        let mut secret = SecretConfig::new();
        secret.set_provider(Some("plain".to_string()));
        secret.set_value(Some(value.to_string()));
        secret
    }

    fn provider_secret_not_found(secret: &str) -> FnoxError {
        FnoxError::ProviderSecretNotFound {
            provider: "plain".to_string(),
            secret: secret.to_string(),
            hint: String::new(),
            url: "https://fnox.jdx.dev/providers".to_string(),
        }
    }

