   793	async fn resolve_with_cache(
   794	    config: &Config,
   795	    profile: &str,
   796	    secrets: IndexMap<String, SecretConfig>,
   797	    req: &ResolveBatchRequest,
   798	    state: std::sync::Arc<Mutex<DaemonState>>,
   799	) -> Result<IndexMap<String, Option<String>>> {
   800	    let fingerprint = config_fingerprint(config, &req.env)?;
   801	    let providers = config.get_providers(profile);
   802	    let mut results = IndexMap::new();
   803	    let mut misses = IndexMap::new();
   804	    let mut miss_keys = HashMap::new();
   805	
   806	    {
   807	        let state = state.lock().await;
   808	        for (key, secret) in &secrets {
   809	            let cacheable = req.purpose != Purpose::Check.as_str()
   810	                && secret.daemon_cache.unwrap_or(true)
   811	                && secret
   812	                    .provider()
   813	                    .and_then(|p| providers.get(p))
   814	                    .is_none_or(|p| p.daemon_cache_enabled());
   815	            if cacheable {
   816	                let cache_key = cache_key(&fingerprint, profile, key, secret, req);
   817	                if let Some(value) = state.cache.get(&cache_key) {
   818	                    results.insert(key.clone(), value.clone());
   819	                    continue;
   820	                }
   821	                miss_keys.insert(key.clone(), cache_key);
   822	            }
   823	            misses.insert(key.clone(), secret.clone());
   824	        }
   825	    }
   826	
   827	    if !misses.is_empty() {
   828	        let resolved = resolve_secrets_batch(config, profile, &misses).await?;
   829	        let mut state = state.lock().await;
   830	        for (key, value) in resolved {
   831	            if let Some(cache_key) = miss_keys.remove(&key) {
   832	                state.cache.insert(cache_key, value.clone());
   833	            }
   834	            results.insert(key, value);
   835	        }
   836	    }
   837	
   838	    let mut ordered = IndexMap::new();
   839	    for key in secrets.keys() {
   840	        if let Some(value) = results.swap_remove(key) {
   841	            ordered.insert(key.clone(), value);
   842	        }
   843	    }
   844	    Ok(ordered)
   845	}
   846	
   847	fn cache_key(
   848	    fingerprint: &str,
   849	    profile: &str,
   850	    key: &str,
   721	/// Secrets are resolved in dependency order using Kahn's algorithm. If a provider
   722	/// declares env var dependencies (e.g., 1Password needs `OP_SERVICE_ACCOUNT_TOKEN`),
   723	/// and another secret provides that env var (e.g., an age-encrypted secret named
   724	/// `OP_SERVICE_ACCOUNT_TOKEN`), the dependency is resolved first. Between resolution
   725	/// levels, resolved values are set as environment variables so subsequent providers
   726	/// can read them.
   727	///
   728	/// Returns an error immediately if any secret with `if_missing = "error"` fails to resolve.
   729	pub async fn resolve_secrets_batch(
   730	    config: &Config,
   731	    profile: &str,
   732	    secrets: &IndexMap<String, SecretConfig>,
   733	) -> Result<IndexMap<String, Option<String>>> {
   734	    // Classify each secret: provider-backed vs no-provider
   735	    let mut secret_provider: HashMap<String, (String, String)> = HashMap::new(); // key -> (provider_name, provider_value)
   736	    let mut no_provider = Vec::new();
   737	
   738	    let providers = config.get_providers(profile);
   739	    let all_keys: Vec<String> = secrets.keys().cloned().collect();
   740	    let secret_keys: HashSet<&str> = all_keys.iter().map(|k| k.as_str()).collect();
   741	    let mut default_deps: HashMap<String, Vec<String>> = HashMap::new();
   742	    let mut hard_default_deps: HashMap<String, Vec<String>> = HashMap::new();
   743	
   744	    for (key, secret_config) in secrets {
   745	        // If a sync cache exists, use the sync provider/value
   746	        if let Some(ref sync) = secret_config.sync {
   747	            secret_provider.insert(key.clone(), (sync.provider.clone(), sync.value.clone()));
   748	            continue;
   749	        }
   750	
   751	        if let Some(provider_value) = secret_config.value() {
   752	            let provider_name = if let Some(provider_name) = secret_config.provider() {
   753	                provider_name.to_string()
   754	            } else if let Ok(Some(default_provider)) = config.get_default_provider(profile) {
   755	                default_provider
   756	            } else {
   757	                no_provider.push(key.clone());
   758	                continue;
   759	            };
   760	
   761	            secret_provider.insert(key.clone(), (provider_name, provider_value.to_string()));
   762	        } else {
   763	            no_provider.push(key.clone());
   764	        }
   765	    }
   766	
   767	    let no_provider_set: HashSet<&str> = no_provider.iter().map(|s| s.as_str()).collect();
   768	    for (key, secret_config) in secrets {
   769	        let provider_is_unconfigured = secret_provider
   770	            .get(key)
   771	            .is_some_and(|(provider_name, _)| !providers.contains_key(provider_name));
   772	        let hard_default = no_provider_set.contains(key.as_str()) || provider_is_unconfigured;
   773	
   774	        let Some(default) = &secret_config.default else {
   775	            continue;
   776	        };
   777	
   778	        let refs = extract_default_references(default);
   779	        if hard_default && refs.iter().any(|reference| reference == key) {
   780	            return Err(FnoxError::Config(format!(
   781	                "Secret '{}' has an interpolation cycle in default value",
   782	                key
   783	            )));
   784	        }
   785	
   786	        let mut deps = Vec::new();
   787	        for reference in refs {
   788	            if secret_keys.contains(reference.as_str()) {
   789	                deps.push(reference);
   790	            } else if hard_default {
   791	                return Err(default_reference_error(key, &reference));
   792	            }
   793	        }
   794	
   795	        if !deps.is_empty() {
   796	            default_deps.insert(key.clone(), deps.clone());
   797	            if hard_default {
   798	                hard_default_deps.insert(key.clone(), deps);
   799	            }
   800	        }
   801	    }
   802	
   803	    // Build dependency graph and compute resolution levels using Kahn's algorithm.
   804	    let mut deps_for_secret: HashMap<String, Vec<String>> = HashMap::new();
   805	    for (key, (provider_name, _)) in &secret_provider {
   806	        let deps = providers
   807	            .get(provider_name)
   808	            .map(|pc| pc.env_dependencies())
   809	            .unwrap_or(&[]);
   810	        deps_for_secret.insert(
   811	            key.clone(),
   812	            deps.iter().map(|dep| dep.to_string()).collect(),
   813	        );
   814	    }
   815	    for (key, refs) in &default_deps {
   816	        match deps_for_secret.entry(key.clone()) {
   817	            Entry::Occupied(mut entry) => {
   818	                let deps = entry.get_mut();
   819	                for reference in refs {
   820	                    if !deps.iter().any(|dep| dep == reference) {
   821	                        deps.push(reference.clone());
   822	                    }
   823	                }
   824	            }
   825	            Entry::Vacant(entry) => {
   826	                entry.insert(refs.clone());
   827	            }
   828	        }
   829	    }
   830	
   831	    let (levels, cycle) = compute_resolution_levels(&all_keys, &deps_for_secret, &no_provider_set);
   832	
   833	    // Resolve each level in order
   834	    let mut temp_results: HashMap<String, Option<String>> = HashMap::new();
   835	
   836	    for ready in &levels {
   837	        let level_results = resolve_level(
   838	            config,
   839	            profile,
   840	            secrets,
   841	            &secret_provider,
   842	            &no_provider,
   843	            ready,
   844	            &temp_results,
   845	        )
   846	        .await?;
   847	
   848	        // Set resolved env vars so next level's providers can see them
   849	        for (key, value) in &level_results {
   850	            if let Some(val) = value {
   851	                env::set_var(key, val);
   852	            }
   853	        }
   854	
   855	        temp_results.extend(level_results);

