   748	            continue;
   749	        }
   750	
   751	        if let Some(provider_value) = secret_config.value() {
   752	            let provider_name = if let Some(provider_name) = secret_config.provider() {
   753	                provider_name.to_string()
   754	            } else if let Ok(Some(default_provider)) = config.get_default_provider(profile) {
   755	                default_provider
   756	            } else {
   757	                no_provider.push(key.clone());
   758	                continue;
   759	            };
