}

impl EnvOverlay {
    fn apply(env: &[(String, String)]) -> Result<Self> {
        let incoming = env
            .iter()
            .map(|(key, _)| key.as_str())
            .collect::<HashSet<_>>();
        let mut touched = env
            .iter()
            .map(|(key, _)| key.clone())
            .collect::<HashSet<_>>();
        for (key, _) in std::env::vars() {
            if !incoming.contains(key.as_str()) {
